pages = sorted(pathlib.Path('docs').glob('*.html'))
bad, titles = [], {}
for f in pages:
    h = f.read_text(encoding='utf-8')
    t = re.search(r'<title>([^<]+)</title>', h).group(1)
    titles.setdefault(t, []).append(f.name)
    if not re.search(r'name=\x22description\x22[^>]+content=\x22[^\x22]{40,}', h): bad.append(f.name + ':description')
    if 'rel=\x22canonical\x22' not in h: bad.append(f.name + ':canonical')
    if 'property=\x22og:' not in h: bad.append(f.name + ':og')
    if 'application/ld+json' not in h: bad.append(f.name + ':json-ld')
for t, names in titles.items():
    if len(names) > 1: bad.append('duplicate title: ' + ','.join(names))
print('pages', len(pages), 'distinct titles', len(titles), 'problems', bad[:3])
assert not bad"
